import React, { useState } from "react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";

export default function SignupPage() {
  const [message, setMessage] = useState("");
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: "",
    email: "",
    password: "",
    cpassword: "",
  });

  const Validate = {
    name: (v) => {
      if (!v.trim()) return "Name is required.";
      if (v.trim().length < 5) return "Name must be at least 5 characters.";
      return "";
    },
    email: (v) => {
      if (!v.trim()) return "Email is required.";
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))
        return "Invalid email format.";
      return "";
    },
    password: (v) => {
      if (!v.trim()) return "Password is required.";
      if (v.length < 6) return "Password must be at least 6 characters.";
      return "";
    },
    cpassword: (pass, cpass) => {
      if (pass !== cpass) return "Passwords do not match.";
      return "";
    },
  };

  const handleForm = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setMessage("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const nameError = Validate.name(form.name);
    const emailError = Validate.email(form.email);
    const passError = Validate.password(form.password);
    const cpassError = Validate.cpassword(form.password, form.cpassword);

    if (nameError || emailError || passError || cpassError) {
      setMessage(nameError || emailError || passError || cpassError);
      return;
    }

    try {
      const res = await axios.post(
        "http://localhost:5000/signup",
        form
      );

      // ✅ backend ka message use karo
      alert(res.data.message);

      // ✅ signup ke baad login page pe redirect
      navigate("/login");

    } catch (err) {
      setMessage(err.response?.data?.message || "Server error");
    }
  };
  return (
    <div id ="signup" style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>Create Account ✨</h2>
        <p style={styles.subtitle}>Join DailyCode and start coding smarter</p>

        <form style={styles.form} onSubmit={handleSubmit}>
          <input
            type="text"
               name="name"
            placeholder="Enter The Full Name"
            value={form.name}
            style={styles.input}
            onChange={handleForm}
          />
          <input
            type="text"
               name="email"
            placeholder="Enter the Email"
             value={form.email}
            style={styles.input}
            onChange={handleForm}
          />
          <input
            type="password"
                  name="password"
            placeholder="Enter the Password"
            value={form.password}
            style={styles.input}
            onChange={handleForm}
          />
          <input
            type="password"
            name="cpassword"
            placeholder="Confirm Password"
            value={form.cpassword}
            style={styles.input}
            onChange={handleForm}
          />

          <button type="submit" style={styles.button}>
            Sign Up
          </button>
        </form>

        <p style={styles.footer}>
          Already have an account?{" "}
          <a href="#login" style={styles.link}>Log in</a>
        </p>
      </div>
    </div>
  );
}

const styles = {
  container: {
    height: "100vh",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    background: "linear-gradient(135deg, #0f172a, #1e3a8a)", // dark gradient
    fontFamily: "sans-serif",
    padding: "1rem",
  },

  card: {
    background: "rgba(255, 255, 255, 0.1)", // glassmorphism
    backdropFilter: "blur(12px)",
    borderRadius: "16px",
    padding: "2rem",
    width: "100%",
    maxWidth: "420px",
    color: "white",
    boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
    textAlign: "center",
  },

  title: {
    fontSize: "1.8rem",
    fontWeight: "bold",
    marginBottom: "0.5rem",
    color: "#38bdf8", // accent cyan
  },

  subtitle: {
    fontSize: "0.95rem",
    marginBottom: "1.5rem",
    color: "#e5e7eb",
  },

  form: {
    display: "flex",
    flexDirection: "column",
    gap: "1rem",
  },

  input: {
    padding: "0.8rem",
    borderRadius: "8px",
    border: "none",
    outline: "none",
    fontSize: "1rem",
    background: "rgba(255,255,255,0.2)",
    color: "white",
    transition: "0.3s",
  },

  button: {
    padding: "0.9rem",
    borderRadius: "8px",
    border: "none",
    background: "linear-gradient(135deg, #38bdf8, #2563eb)",
    color: "white",
    fontSize: "1rem",
    fontWeight: "bold",
    cursor: "pointer",
    transition: "0.3s",
  },

  footer: {
    marginTop: "1.5rem",
    fontSize: "0.9rem",
    color: "#d1d5db",
  },

  link: {
    color: "#38bdf8",
    textDecoration: "none",
    fontWeight: "bold",
  },
};
